local function hex(h: string): Color3
	return Color3.fromHex(h)
end

-- 2. Every MeshPart under Kit, by name. Each Model is named after its FBX file and many MeshParts share their
-- Model's name (CashBag inside CashBag, Safe inside Safe), so FindFirstChild(name, true) would return the Model:
-- never look kit pieces up that way (tests/kit_check.luau must not either).
local parts: { [string]: MeshPart } = {}
local problems = 0
for _, d in kit:GetDescendants() do
	if d:IsA("MeshPart") then
		if parts[d.Name] then
			problems += 1
			warn("DUPLICATE MeshPart name", d:GetFullName(), "and", parts[d.Name]:GetFullName())
		else
			parts[d.Name] = d
		end
		if not WANT[d.Name] then
			warn("NOT IN THE MANIFEST (an old or renamed piece: delete it)", d:GetFullName())
		end
	end
end

-- 3. The kit atlas: the first TextureID the importer uploaded, unless ATLAS is set.
local atlas = uri(ATLAS)
if atlas == "" then
	for name, p in parts do
		local w = WANT[name]
		if w and w.atlas then
			if p.TextureID ~= "" then
				atlas = p.TextureID
				break
			end
			local sa = p:FindFirstChildOfClass("SurfaceAppearance")
			local found = sa and sa.ColorMapContent.Uri
			if found and found ~= "" then
				atlas = found
				break
			end
		end
	end
end
print("Kit atlas texture:", atlas ~= "" and atlas or "NOT FOUND: upload assets/textures/EH_Palette_Bank.png, paste its id in ATLAS")

-- 4. Same look on every piece, then check it.
for name, w in WANT do
	local p = parts[name]
	if p == nil then
		problems += 1
		warn("MISSING", name, "(import " .. w.model .. ".fbx)")
		continue
	end
	local model = p:FindFirstAncestorOfClass("Model")
	if model == nil or model.Name ~= w.model then
		problems += 1
		warn("WRONG MODEL", p:GetFullName(), "belongs in the Model", w.model)
	end
	for _, sa in p:GetChildren() do
		if sa:IsA("SurfaceAppearance") and not w.texture then
			sa:Destroy()
		end
	end
	if w.texture then -- the hero SurfaceAppearance (vault combination face)
		local sa = p:FindFirstChildOfClass("SurfaceAppearance") or Instance.new("SurfaceAppearance")
		if DIALFACE_COLOR ~= "" then
			sa.ColorMapContent = Content.fromUri(uri(DIALFACE_COLOR))
		end
		if DIALFACE_ROUGHNESS ~= "" then
			sa.RoughnessMapContent = Content.fromUri(uri(DIALFACE_ROUGHNESS))
		end
		if DIALFACE_EMISSIVE ~= "" then
			sa.EmissiveMaskContent = Content.fromUri(uri(DIALFACE_EMISSIVE))
		end
		sa.EmissiveStrength = 2
		sa.EmissiveTint = hex("#A8987A")
		sa.Parent = p
	end
	p.Material = Enum.Material[w.material]
	p.TextureID = if w.atlas then atlas else ""
	p.Color = if w.color then hex(w.color) else Color3.new(1, 1, 1)
	p.Transparency = w.transparency or 0
	p.Anchored = true
	p.CanCollide = w.canCollide
	p.CanTouch = w.canCollide
	p.CastShadow = w.castShadow
	local sizeOk = (p.Size - w.size).Magnitude < 0.05
	local nativeOk = (p.Size - p.MeshSize).Magnitude < 0.05
	local collOk = p.CollisionFidelity.Name == w.collision
	if not (sizeOk and nativeOk and collOk) then
		problems += 1
	end
	print(string.format("%-26s size %s %s | native %s | collision %s %s", name, tostring(p.Size),
		sizeOk and "ok" or ("WANT " .. tostring(w.size)), nativeOk and "ok" or "SCALED IN STUDIO",
		p.CollisionFidelity.Name, collOk and "ok" or ("SET TO " .. w.collision)))
end

-- 5. Axis checks: the vault dial must sit on the front (-Z, the LookVector side) of the frame, and Gus's
-- right hand (the torch) on +X (the RightVector side of a -Z-facing character).
local frame, dial = parts.VaultDoor_Frame, parts.VaultDoor_Dial
if frame and dial then
	print("Vault front faces -Z:", dial.Position.Z < frame.Position.Z and "yes" or "NO, tell Claude (FBX axis)")
end
local torso, torch = parts.Gus_UpperTorso, parts.Gus_Flashlight
if torso and torch then
	print("Gus torch on his right (+X):", torch.Position.X > torso.Position.X and "yes" or "NO, tell Claude (FBX X axis)")
end
print(problems == 0 and "KIT OK" or (problems .. " problem(s): fix them, then run again"))
